const courseGroup=(names,level,stream,source,campus,duration=null,eligibility=null)=>names.map(name=>{
 const text=name.toLowerCase();
 const inferredLevel=level.includes('/')
  ? (/^pre-university/.test(text)?'Pre-University':/^pharm\.?\s*d\b/.test(text)?'Professional Doctorate':/^ph\.d|^doctor of philosophy/.test(text)?'Doctoral':/^(m\.|master|post basic|post b\.)|^mba|^mca|^m\.com|^m\.sc|^m\.a|^m\.pharm|^m\.pt/.test(text)?'Postgraduate':/^(d\.|diploma|general nursing)/.test(text)?'Diploma':'Undergraduate')
  : level;
 let inferredStream=stream;
 if(stream==='Arts, Commerce, Health and Professional Studies'){
  if(/pharm/.test(text))inferredStream='Pharmacy';
  else if(/nurs/.test(text))inferredStream='Nursing';
  else if(/physiotherapy|\bm\.pt|\bbpt/.test(text))inferredStream='Physiotherapy';
  else if(/hospital administration|medical|occupational therapy|optometry|dialysis|anaesthesia|respiratory/.test(text))inferredStream='Allied Health';
  else if(/journalism|english/.test(text))inferredStream='Arts and Humanities';
  else if(/commerce|\bb\.com|\bm\.com/.test(text))inferredStream='Commerce';
  else if(/computer|\bb\.c.a|\bm\.c.a/.test(text))inferredStream='Computer Applications';
  else if(/business|\bmba|\bbba|management|logistic/.test(text))inferredStream='Management';
  else inferredStream='Science';
 }
 return {name,level:inferredLevel,stream:inferredStream,campus,duration,eligibility,source};
});
const facilities=(source,entries)=>entries.map(([name,description])=>({name,description,source}));
const logoSource=(label,url)=>({kind:'logo',label,url,license:'Official institutional logo; trademark remains with its owner. Displayed only to identify the institution.'});
const campusCandidate=(label,url)=>({kind:'campus',label,url,license:'Sourced from official institutional media; copyright remains with the institution.'});

